// archive/test.js - unit tests of the archive library: `node archive/test.js` (importing the module runs nothing).
// Core formats here (I/O, Deflate / Deflate64, gzip, compress, LZMA / LZMA2 / xz, bzip2, branch filters, 7z, ZIP
// incl. ZipCrypto / WinZip AES and the ZIP writer, tar incl. pax / GNU / sparse, detection, volumes, openArchive),
// then the suites of the other modules (test-ppmd.js, test-rar.js, test-iso.js, test-arc.js, test-pkware.js,
// test-libarchive.js).
//
// Archives are made on the fly with the tools of the machine when they exist (7-Zip, bsdtar, Python's lzma / bz2 /
// zipfile); otherwise small embedded fixtures (made with those tools, see makeFixtures()) keep the suite meaningful.
// Encoders written for the tests only (tar, compress, gzip members) cover what the tools cannot make.

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import zlib from 'node:zlib';
import { crc32 } from '../codec/crc32.js';
import { Inflater } from '../codec/zlib.js';
import { ZipWriter, listZip } from '../zip/zip.js';
import { bzip2Stream } from './bzip2.js';
import { detectFormat, groupVolumes } from './detect.js';
import { FILTERS } from './filters.js';
import { gzipStream, lzwStream } from './gzip.js';
import { cleanPath, openArchive } from './index.js';
import { ArchiveError, Reader, bytesSource, bytesStream, concatSource, crcStream, decodeText, guessCharset, limitStream, readAll } from './io.js';
import { lzma2Stream, lzmaAloneStream, lzmaStream } from './lzma.js';
import { openSevenZip } from './sevenzip.js';
import { listTar, openTar } from './tar.js';
import { crc64, xzStream } from './xz.js';
import { xxh64, zstdStream } from './zstd.js';
import { openZip } from './zip.js';

const isMain = typeof process !== 'undefined' && process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
const te = new TextEncoder();
const b64 = (s) => new Uint8Array(Buffer.from(s, 'base64'));

// --- sample data ---------------------------------------------------------------------------------------------

// Seeded LCG (glibc constants) instead of Math.random: inputs are reproducible, so a failure seen once can be
// re-run identically, and embedded fixtures stay valid across runs.
function lcg(seed) { let x = seed >>> 0; return () => (x = (Math.imul(x, 1103515245) + 12345) >>> 0); }
const WORDS = 'alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi omicron pi rho sigma tau archive'.split(' ');
export function textBytes(n, seed = 1) {
  const r = lcg(seed);
  let s = '';
  while (s.length < n) { const v = r(); s += WORDS[(v >>> 16) % WORDS.length] + ((v >>> 8) % 11 ? ' ' : '\n'); }
  return te.encode(s.slice(0, n));
}
export function randomBytes(n, seed = 2) { const r = lcg(seed), b = new Uint8Array(n); for (let i = 0; i < n; i++) b[i] = r() >>> 24; return b; }
// Machine-code-like bytes: x86 CALL / JMP patterns and ARM64 BL / ADRP words among random bytes.
export function exeBytes(n, seed = 3) {
  const b = randomBytes(n, seed);
  for (let i = 0; i + 8 <= n; i += 37) { b[i] = 0xe8; b[i + 4] = i % 2 ? 0 : 0xff; }
  for (let i = 16; i + 4 <= n; i += 64) { b[i + 3] = 0x94; b[i + 2] &= 0x3; }
  for (let i = 48; i + 4 <= n; i += 128) { b[i + 3] = 0x90 | (b[i + 3] & 0x60); b[i] = (b[i] & 0xe0) | 3; }
  return b;
}

/** The test tree: { path: bytes | null (directory) }. scale = 1 for embedded fixtures, larger with tools. */
export function makeTree(scale = 1) {
  return {
    'text.txt': textBytes(3000 * scale), 'random.bin': randomBytes(200 * scale), 'zeros.bin': new Uint8Array(4000 * scale),
    'empty.txt': new Uint8Array(0), 'prog.exe': exeBytes(1000 * scale), 'dir': null, 'dir/sub': null, 'emptydir': null,
    'dir/sub/note.md': te.encode('# Привет мир\nΓειά σου κόσμε\n日本語\n'.repeat(4 * scale)), 'dir/Ünïcödé — файл.txt': te.encode('unicode name\n'),
  };
}

function writeTree(dir, tree) {
  for (const [p, d] of Object.entries(tree)) {
    const f = path.join(dir, p);
    if (d === null) fs.mkdirSync(f, { recursive: true });
    else { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, d); }
  }
}

// --- tools -------------------------------------------------------------------------------------------------------

// ARCHIVE_TEST_NO_TOOLS=1 runs the suite as on a machine without the tools (embedded fixtures only).
const NO_TOOLS = typeof process !== 'undefined' && !!process.env.ARCHIVE_TEST_NO_TOOLS;
const SZ = NO_TOOLS ? null : ['C:/Program Files/7-Zip/7z.exe', 'C:/Program Files (x86)/7-Zip/7z.exe', '/usr/bin/7z', '/usr/bin/7zz', '/usr/local/bin/7z', '/opt/homebrew/bin/7z'].find((p) => fs.existsSync(p)) || null;
const BSDTAR = NO_TOOLS ? null : ['C:/Windows/System32/tar.exe', '/usr/bin/bsdtar', '/opt/homebrew/bin/bsdtar'].find((p) => fs.existsSync(p)) || null;
let PY = null;
for (const c of NO_TOOLS ? [] : process.platform === 'win32' ? ['py', 'python'] : ['python3', 'python']) {
  try { execFileSync(c, ['-c', 'import lzma, bz2, zipfile'], { stdio: 'ignore' }); PY = c; break; } catch { /* next */ }
}
const exec = (cmd, args, opts = {}) => execFileSync(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 1 << 28, ...opts });

// <fixtures> (generated by makeFixtures(): base64 archives of makeTree(1); do not edit by hand)
const FIXTURES = {
  'lzma2.7z':
    '',
  'bcj2.7z':
    '',
  'arm64.7z':
    '',
  'delta-bzip2.7z':
    '',
  'pw-mhe.7z':
    '',
  'deflate64.zip':
    '',
  'lzma.zip':
    '',
  'pw-crypto.zip':
    '',
  'pw-aes.zip':
    '',
  'text.xz':
    '',
  'text.lzma':
    '',
  'text.bz2':
    '',
  'text.zst':
    '',
};
// </fixtures>
export { FIXTURES };

// --- the suite ---------------------------------------------------------------------------------------------------

export async function run() {
  let pass = 0, fail = 0;
  const ok = (name, cond, extra) => { if (cond) pass++; else { fail++; console.log('  FAIL ' + name + (extra !== undefined ? ': ' + String(extra).slice(0, 300) : '')); } };
  const eq = (a, b) => a && b && a.length === b.length && Buffer.from(a.buffer, a.byteOffset, a.length).equals(Buffer.from(b.buffer, b.byteOffset, b.length));
  const throwsCode = (name, fn, code) => { try { fn(); ok(name, false, 'no error'); } catch (e) { ok(name, e instanceof ArchiveError && e.code === code, e.code + ' ' + e.message); } };
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'archive-test-'));
  const tree = makeTree(1), big = makeTree(40);
  const checkArchive = (name, arc, want, { skipDirs = false } = {}) => {
    const seen = new Set();
    let bad = '';
    for (const e of arc.entries) {
      seen.add(e.path);
      if (!(e.path in want)) { bad += ' extra:' + e.path; continue; }
      if (want[e.path] === null) { if (!e.dir) bad += ' notdir:' + e.path; continue; }
      try { if (!eq(readAll(arc.open(e)), want[e.path])) bad += ' data:' + e.path; } catch (err) { bad += ` err:${e.path}:${err.code}:${err.message}`; }
    }
    for (const p of Object.keys(want)) if (!seen.has(p) && !(skipDirs && want[p] === null)) bad += ' missing:' + p;
    ok(name, !bad, bad);
  };
  try {
    // io --------------------------------------------------------------------------------------------------------
    {
      const parts = [te.encode('hello '), te.encode('wor'), te.encode('ld!')];
      const cs = concatSource(parts.map((p) => bytesSource(p)));
      ok('io concat size', cs.size === 12);
      ok('io concat read across parts', new TextDecoder().decode(cs.read(4, 6)) === 'o worl');
      const r = new Reader(bytesStream(te.encode('abcdef')), 2);
      ok('io reader', r.byte() === 97 && new TextDecoder().decode(r.bytes(3)) === 'bcd' && r.pos === 4);
      r.skip(1);
      ok('io reader end', r.byte() === 102 && r.byte() === -1 && r.eof());
      throwsCode('io limit truncated', () => readAll(limitStream(bytesStream(te.encode('abc')), 5)), 'truncated');
      throwsCode('io crc mismatch', () => readAll(crcStream(bytesStream(te.encode('abc')), 1)), 'checksum');
      ok('io crc ok', readAll(crcStream(bytesStream(te.encode('abc')), crc32(te.encode('abc')))).length === 3);
      const cp866 = Uint8Array.from([0x8f, 0xe0, 0xa8, 0xa2, 0xa5, 0xe2]), w1251 = Uint8Array.from([0xcf, 0xf0, 0xe8, 0xe2, 0xe5, 0xf2]);
      ok('charset guess cp866', guessCharset(cp866) === 'ibm866' && decodeText(cp866) === 'Привет');
      ok('charset guess 1251', guessCharset(w1251) === 'windows-1251' && decodeText(w1251) === 'Привет');
      ok('charset utf-8', decodeText(te.encode('Ünï')) === 'Ünï' && decodeText(Uint8Array.from([0x80, 0x81]), 'cp437') === 'Çü');
      ok('cleanPath', cleanPath('../a/./b//c/..').path === 'a/b/c' && cleanPath('../x').unsafe && !cleanPath('a/b').unsafe);
    }
    // Deflate (node:zlib as the reference encoder) --------------------------------------------------------------
    for (const [name, data] of [['text', big['text.txt']], ['random', big['random.bin']], ['zeros', big['zeros.bin']], ['empty', new Uint8Array(0)], ['exe', big['prog.exe']]]) {
      for (const level of [0, 1, 6, 9]) {
        const z = zlib.deflateRawSync(data, { level });
        for (const step of [1, 777, 1 << 20]) {
          const inf = new Inflater(new Reader(bytesStream(z), step === 1 ? 3 : 4096), { size: step === 777 ? data.length : 0 });
          const out = [];
          for (let b; (b = inf.read(step === 1 ? 1000 : step));) out.push(b.slice());
          ok(`inflate ${name} level ${level} step ${step}`, eq(Buffer.concat(out), data));
        }
      }
    }
    try { const inf = new Inflater(new Reader(bytesStream(Uint8Array.from([0xff, 0xff, 0xff, 0xff])))); while (inf.read()); ok('inflate corrupt', false); } catch (e) { ok('inflate corrupt', /invalid deflate data/.test(e.message), e.message); }
    // gzip: multi-member, names, CRC errors, trailing zeros
    {
      const a = textBytes(30000, 5), b = randomBytes(5000, 6);
      const gz = Buffer.concat([zlib.gzipSync(a), zlib.gzipSync(b), Buffer.alloc(512)]);
      ok('gzip multi-member + padding', eq(readAll(gzipStream(new Reader(bytesStream(gz)))), Buffer.concat([a, b])));
      const bad = Buffer.from(zlib.gzipSync(a)); bad[bad.length - 6] ^= 1;
      try { readAll(gzipStream(new Reader(bytesStream(bad)))); ok('gzip crc error', false); } catch (e) { ok('gzip crc error', e.code === 'checksum', e.message); }
      // FNAME header written by hand
      const body = zlib.deflateRawSync(a);
      const head = Buffer.concat([Buffer.from([0x1f, 0x8b, 8, 8, 0, 0, 0, 0, 0, 3]), Buffer.from('notes.txt\0', 'latin1')]);
      const tail = Buffer.alloc(8); tail.writeUInt32LE(crc32(a), 0); tail.writeUInt32LE(a.length, 4);
      const arc = openArchive([bytesSource(Buffer.concat([head, body, tail]), 'x.gz')]);
      ok('gzip FNAME entry', arc.entries.length === 1 && arc.entries[0].path === 'notes.txt' && arc.entries[0].size === a.length && eq(readAll(arc.open(arc.entries[0])), a));
    }
    // compress (.Z) with a test-only LZW encoder (block mode, codes in groups, width growth, table clears)
    for (const [name, data, maxBits] of [['text', big['text.txt'], 16], ['random', big['random.bin'], 12], ['small', textBytes(100, 9), 9], ['empty', new Uint8Array(0), 16], ['zeros', new Uint8Array(200000), 10]]) {
      const z = compressZ(data, maxBits);
      const got = readAll((() => { const r = new Reader(bytesStream(z)); r.skip(2); return lzwStream(r); })());
      ok(`compress ${name} ${maxBits} bits`, eq(got, data), got.length + ' vs ' + data.length);
      if (SZ && data.length) {
        const f = path.join(tmp, `c-${name}.Z`);
        fs.writeFileSync(f, z);
        try { ok(`compress ${name}: 7-Zip agrees`, eq(exec(SZ, ['e', '-so', f]), data)); } catch (e) { ok(`compress ${name}: 7-Zip agrees`, false, e.message); }
      }
    }
    // tar written by a test-only writer: ustar prefix, pax path / size / times, GNU long name, symlink, hard link, sparse
    {
      const files = [
        { name: 'a.txt', data: te.encode('first file\n') },
        { name: 'deep/' + 'x'.repeat(120) + '/file.bin', data: randomBytes(3000, 11), pax: true },
        { name: 'gnu/' + 'y'.repeat(130) + '.txt', data: te.encode('gnu long name'), gnuLong: true },
        { name: 'pre/' + 'p'.repeat(90) + '/' + 'q'.repeat(40) + '.dat', data: te.encode('ustar prefix'), ustarPrefix: true },
        { name: 'dir/', dir: true },
        { name: 'link', symlink: 'a.txt' },
        { name: 'hard', hardlink: 'a.txt' },
        { name: 'sparse.img', sparse: [[0, 512], [8192, 1024], [65536, 100]], size: 70000 },
        { name: 'sparse-pax.img', paxSparse: [[1024, 2048], [40000, 500]], size: 50000 },
      ];
      const tarBytes = makeTar(files);
      const arc = openTar([bytesSource(tarBytes)]);
      const by = Object.fromEntries(arc.entries.map((e) => [e.path, e]));
      ok('tar names (ustar prefix, pax, GNU long)', files.every((f) => by[f.name.replace(/\/$/, '')]), Object.keys(by).join(','));
      ok('tar data', eq(readAll(arc.open(by['a.txt'])), files[0].data) && eq(readAll(arc.open(by[files[1].name])), files[1].data) && eq(readAll(arc.open(by[files[2].name])), files[2].data));
      ok('tar symlink / hardlink', by.link.kind === 'symlink' && by.link.link === 'a.txt' && by.hard.kind === 'hardlink' && eq(readAll(arc.open(by.hard)), files[0].data));
      for (const s of ['sparse.img', 'sparse-pax.img']) {
        const f = files.find((x) => x.name === s);
        ok('tar ' + s, by[s].size === f.size && eq(readAll(arc.open(by[s])), sparseImage(f.sparse || f.paxSparse, f.size)), by[s] && by[s].size);
      }
      ok('tar mtime', by['a.txt'].mtime.getTime() === 1700000000000);
      // the same tar inside gzip (cursor-based extraction in any order)
      const tgz = openArchive([bytesSource(zlib.gzipSync(tarBytes), 'x.tgz')]);
      const tb = Object.fromEntries(tgz.entries.map((e) => [e.path, e]));
      ok('tar.gz listing', tgz.format === 'tar.gzip' && tgz.entries.length === arc.entries.length);
      ok('tar.gz out of order', eq(readAll(tgz.open(tb[files[1].name])), files[1].data) && eq(readAll(tgz.open(tb['a.txt'])), files[0].data));
      if (BSDTAR) {
        const f = path.join(tmp, 'mine.tar');
        fs.writeFileSync(f, tarBytes);
        try { const list = String(exec(BSDTAR, ['-tf', f])); ok('tar writer is valid for bsdtar', list.includes('sparse.img') && list.includes('gnu/')); } catch (e) { ok('tar writer is valid for bsdtar', false, e.message); }
      }
    }
    // ZipWriter -> openZip, and 7-Zip test of the output
    for (const method of ['store', 'deflate']) {
      const w = new ZipWriter({ method });
      for (const [p, d] of Object.entries(big)) {
        if (d === null) await w.add(p + '/', null, { dir: true });
        else await w.add(p, method === 'store' ? d : (async function* () { for (let i = 0; i < d.length; i += 7000) yield d.subarray(i, i + 7000); })(), { time: new Date(2020, 1, 2, 3, 4, 6) });
      }
      await w.add('text.txt', te.encode('duplicate name'));
      const zip = new Uint8Array(await (await w.finish()).arrayBuffer());
      const arc = openZip([bytesSource(zip)]);
      const dup = arc.entries.find((e) => e.path === 'text (2).txt');
      const want = { ...big, 'text (2).txt': te.encode('duplicate name') };
      checkArchive('ZipWriter ' + method, arc, want);
      ok('ZipWriter unique names', !!dup);
      ok('ZipWriter time', arc.entries.find((e) => e.path === 'text.txt').mtime.getTime() === new Date(2020, 1, 2, 3, 4, 6).getTime());
      if (SZ) {
        const f = path.join(tmp, `writer-${method}.zip`);
        fs.writeFileSync(f, zip);
        try { const out = String(exec(SZ, ['t', f])); ok('ZipWriter: 7-Zip test ' + method, /Everything is Ok/.test(out), out.slice(-200)); } catch (e) { ok('ZipWriter: 7-Zip test ' + method, false, String(e.stdout || e.message).slice(-300)); }
      }
    }
    // detection and volumes
    {
      ok('groupVolumes', JSON.stringify(groupVolumes(['b.part2.rar', 'x.txt', 'b.part1.rar', 'c.7z.002', 'c.7z.001', 'd.r00', 'd.rar', 'e.z01', 'e.zip', 'f.zip', 'g.r01']))
        === JSON.stringify([[1], [2, 0], [4, 3], [6, 5], [7, 8], [9], [10]]), JSON.stringify(groupVolumes(['b.part2.rar', 'x.txt', 'b.part1.rar', 'c.7z.002', 'c.7z.001', 'd.r00', 'd.rar', 'e.z01', 'e.zip', 'f.zip', 'g.r01'])));
      const det = (b) => (detectFormat(bytesSource(b)) || {}).format;
      ok('detect gzip / bzip2 / xz / Z', det(zlib.gzipSync(te.encode('x'))) === 'gzip' && det(te.encode('BZh91AY&SY')) === 'bzip2' && det(Uint8Array.from([0xfd, 0x37, 0x7a, 0x58, 0x5a, 0, 0, 1])) === 'xz' && det(Uint8Array.from([0x1f, 0x9d, 0x90])) === 'Z');
      ok('detect rar / 7z / zip', det(te.encode('Rar!\x1a\x07\x01\x00....')) === 'rar5' && det(te.encode('Rar!\x1a\x07\x00....')) === 'rar' && det(Uint8Array.from([0x37, 0x7a, 0xbc, 0xaf, 0x27, 0x1c, 0, 4])) === '7z' && det(te.encode('PK\x03\x04')) === 'zip');
      ok('detect unknown', det(te.encode('just some text that is no archive at all')) === undefined);
      throwsCode('openArchive unknown', () => openArchive([bytesSource(te.encode('plain text'))]), 'format');
      throwsCode('openArchive unsupported', () => openArchive([bytesSource(te.encode('LZIP....'))]), 'unsupported');
      ok('xxh64 vectors', xxh64(new Uint8Array(0)).join() === [0x51d8e999, 0xef46db37].join() && xxh64(te.encode('abc')).join() === [0xad770999, 0x44bc2cf5].join());
      ok('detect zstd (and a leading skippable frame)', det(Uint8Array.from([0x28, 0xb5, 0x2f, 0xfd, 0, 0])) === 'zstd' && det(Uint8Array.from([0x50, 0x2a, 0x4d, 0x18, 1, 0, 0, 0, 9, 0x28, 0xb5, 0x2f, 0xfd, 0])) === 'zstd');
    }
    // embedded fixtures (always)
    await fixtureTests(ok, eq, throwsCode, checkArchive, tree);
    // the tools of this machine (when present)
    if (SZ || PY || BSDTAR) await toolTests(ok, eq, throwsCode, checkArchive, big, tmp);
    else console.log('  (no 7-Zip, Python or bsdtar here: embedded fixtures only)');
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
  console.log(`archive: ${pass} passed, ${fail} failed`);
  // The suites of the other modules.
  for (const m of ['test-ppmd.js', 'test-rar.js', 'test-iso.js', 'test-arc.js', 'test-pkware.js', 'test-libarchive.js']) {
    if (!fs.existsSync(new URL('./' + m, import.meta.url))) continue;
    fail += await (await import('./' + m)).run();
  }
  return fail;
}

// --- embedded fixtures -----------------------------------------------------------------------------------------

async function fixtureTests(ok, eq, throwsCode, checkArchive, tree) {
  const src = (k) => bytesSource(b64(FIXTURES[k]), k);
  const text = tree['text.txt'];
  if (!Object.keys(FIXTURES).length) { ok('embedded fixtures present', false); return; }
  for (const k of Object.keys(FIXTURES)) {
    if (/\.(7z|zip)$/.test(k)) {
      try {
        const arc = openArchive([src(k)], { password: k.includes('pw') ? 'fixture' : undefined });
        checkArchive('fixture ' + k, arc, tree);
      } catch (e) { ok('fixture ' + k, false, e.code + ' ' + e.message); }
    } else {
      try {
        const arc = openArchive([src(k)]);
        ok('fixture ' + k, arc.entries.length === 1 && eq(readAll(arc.open(arc.entries[0])), text));
      } catch (e) { ok('fixture ' + k, false, e.code + ' ' + e.message); }
    }
  }
  for (const k of Object.keys(FIXTURES).filter((x) => x.includes('pw'))) {
    try {
      const arc = openArchive([src(k)], { password: 'wrong' });
      const e = arc.entries.find((x) => x.path === 'text.txt');
      readAll(arc.open(e));
      ok('fixture wrong password ' + k, false);
    } catch (e) { ok('fixture wrong password ' + k, e.code === 'badPassword', e.code); }
    if (k.includes('mhe')) throwsCode('fixture no password ' + k, () => openArchive([src(k)]), 'password');
  }
  // damaged copy: a flipped byte in the middle of the data
  const k = Object.keys(FIXTURES).find((x) => x.endsWith('lzma2.7z'));
  if (k) {
    const b = b64(FIXTURES[k]);
    b[64] ^= 0x55;
    try {
      const arc = openArchive([bytesSource(b)]);
      let err = null;
      for (const e of arc.entries) { try { readAll(arc.open(e)); } catch (x) { err = x; } }
      ok('fixture damaged 7z detected', err && /corrupt|checksum|truncated/.test(err.code), err && err.code);
    } catch (e) { ok('fixture damaged 7z detected', /corrupt|checksum|truncated/.test(e.code), e.code); }
  }
}

// --- archives made with the tools ------------------------------------------------------------------------------

async function toolTests(ok, eq, throwsCode, checkArchive, big, tmp) {
  const dir = path.join(tmp, 'src');
  writeTree(dir, big);
  const text = big['text.txt'];
  const open = (files, opts) => openArchive(files.map((f) => bytesSource(fs.readFileSync(f), path.basename(f))), opts);
  if (SZ) {
    const cases = [
      ['lzma', ['-m0=LZMA']], ['lzma2', ['-m0=LZMA2']], ['lzma2-nonsolid', ['-m0=LZMA2', '-ms=off']], ['copy', ['-m0=Copy', '-mhc=off']],
      ['bzip2', ['-m0=BZip2']], ['deflate', ['-m0=Deflate']], ['deflate64', ['-m0=Deflate64']], ['ppmd', ['-m0=PPMd']],
      ['bcj', ['-m0=BCJ', '-m1=LZMA2']], ['bcj2', ['-mf=BCJ2']], ['arm', ['-m0=ARM', '-m1=LZMA2']], ['armt', ['-m0=ARMT', '-m1=LZMA2']],
      ['arm64', ['-m0=ARM64', '-m1=LZMA2']], ['riscv', ['-m0=RISCV', '-m1=LZMA2']], ['ppc', ['-m0=PPC', '-m1=LZMA2']], ['sparc', ['-m0=SPARC', '-m1=LZMA2']], ['ia64', ['-m0=IA64', '-m1=LZMA2']],
      ['delta', ['-m0=Delta:4', '-m1=LZMA2']], ['swap2', ['-m0=Swap2', '-m1=LZMA2']], ['aes', ['-m0=LZMA2', '-psecret']], ['aes-mhe', ['-m0=LZMA2', '-psecret', '-mhe=on']],
    ];
    for (const [name, args] of cases) {
      const out = path.join(tmp, name + '.7z');
      try { exec(SZ, ['a', '-t7z', out, '.', ...args], { cwd: dir }); } catch (e) { ok('7z.exe ' + name, false, e.message); continue; }
      try { checkArchive('7z ' + name, open([out], { password: 'secret' }), big); } catch (e) { ok('7z ' + name, false, e.code + ' ' + e.message); }
    }
    try { open([path.join(tmp, 'aes-mhe.7z')], { password: 'nope' }); ok('7z wrong header password', false); } catch (e) { ok('7z wrong header password', e.code === 'badPassword', e.code); }
    // split volumes, given out of order and named as 7-Zip names them
    exec(SZ, ['a', '-t7z', path.join(tmp, 'vol.7z'), '.', '-v20k'], { cwd: dir });
    const vols = fs.readdirSync(tmp).filter((f) => f.startsWith('vol.7z.')).sort().map((f) => path.join(tmp, f));
    const groups = groupVolumes(vols.map((v) => path.basename(v)).reverse()).map((g) => g.map((i) => vols[vols.length - 1 - i]));
    ok('7z volumes grouped', groups.length === 1 && groups[0].length === vols.length && vols.length > 2);
    checkArchive('7z volumes', open(groups[0]), big);
    try { const arc = open(vols.slice(0, -1)); readAll(arc.open(arc.entries[0])); ok('7z missing volume', false); } catch (e) { ok('7z missing volume', e.code === 'volume' || e.code === 'truncated', e.code); }
    // ZIP methods and encryption
    for (const [name, args] of [['deflate', ['-mm=Deflate']], ['deflate64', ['-mm=Deflate64']], ['bzip2', ['-mm=BZip2']], ['lzma', ['-mm=LZMA']], ['ppmd', ['-mm=PPMd']],
      ['store', ['-mm=Copy']], ['zipcrypto', ['-psecret', '-mem=ZipCrypto']], ['aes128', ['-psecret', '-mem=AES128']], ['aes256', ['-psecret', '-mem=AES256', '-mm=LZMA']]]) {
      const out = path.join(tmp, name + '.zip');
      exec(SZ, ['a', '-tzip', out, '.', ...args], { cwd: dir });
      try { checkArchive('zip ' + name, open([out], { password: 'secret' }), big); } catch (e) { ok('zip ' + name, false, e.code + ' ' + e.message); }
    }
    for (const name of ['zipcrypto', 'aes256']) {
      const arc = open([path.join(tmp, name + '.zip')], { password: 'wrong' });
      try { readAll(arc.open(arc.entries.find((e) => e.path === 'text.txt'))); ok('zip wrong password ' + name, false); } catch (e) { ok('zip wrong password ' + name, e.code === 'badPassword', e.code); }
    }
    // single-stream formats and compressed tars
    for (const [t, ext] of [['gzip', 'gz'], ['bzip2', 'bz2'], ['xz', 'xz']]) {
      const out = path.join(tmp, 'text.txt.' + ext);
      exec(SZ, ['a', '-t' + t, out, path.join(dir, 'text.txt')]);
      const arc = open([out]);
      ok('7-Zip ' + t, arc.entries[0].path === 'text.txt' && eq(readAll(arc.open(arc.entries[0])), text));
    }
  }
  if (BSDTAR) {
    for (const fmt of ['pax', 'gnutar', 'ustar']) {
      const out = path.join(tmp, fmt + '.tar');
      exec(BSDTAR, ['-c', '--format', fmt, '-f', out, '-C', dir, 'text.txt', 'random.bin', 'zeros.bin', 'empty.txt', 'prog.exe', 'emptydir', 'dir/sub']);
      const want = Object.fromEntries(Object.entries(big).filter(([p]) => !p.includes('Ünïcödé') && p !== 'dir'));
      checkArchive('tar ' + fmt, open([out]), want);
    }
    for (const [flag, fmt] of [['-z', 'gzip'], ['-j', 'bzip2'], ['-J', 'xz'], ['--zstd', 'zstd'], ['--lzma', 'lzma']]) {
      const out = path.join(tmp, 'c.tar.' + fmt);
      exec(BSDTAR, ['-c', flag, '--format', 'pax', '-f', out, '-C', dir, '.']);
      const arc = open([out]);
      ok('tar.' + fmt + ' detected', arc.format === 'tar.' + fmt, arc.format);
      checkArchive('tar.' + fmt, arc, big);
    }
  }
  if (PY) {
    const py = (code) => exec(PY, ['-c', code, tmp, dir]);
    py(`
import lzma, bz2, sys, os, zipfile
d, src = sys.argv[1], sys.argv[2]
t = open(os.path.join(src, 'text.txt'), 'rb').read()
open(d + '/a.lzma', 'wb').write(lzma.compress(t, format=lzma.FORMAT_ALONE))
open(d + '/raw1', 'wb').write(lzma.compress(t, format=lzma.FORMAT_RAW, filters=[{'id': lzma.FILTER_LZMA1, 'dict_size': 1 << 16, 'lc': 0, 'lp': 2, 'pb': 0}]))
open(d + '/raw2', 'wb').write(lzma.compress(t, format=lzma.FORMAT_RAW, filters=[{'id': lzma.FILTER_LZMA2, 'dict_size': 1 << 20}]))
for c, n in ((lzma.CHECK_NONE, 'none'), (lzma.CHECK_CRC32, 'crc32'), (lzma.CHECK_CRC64, 'crc64'), (lzma.CHECK_SHA256, 'sha256')):
    open(d + '/c-' + n + '.xz', 'wb').write(lzma.compress(t, check=c))
open(d + '/f.xz', 'wb').write(lzma.compress(t, filters=[{'id': lzma.FILTER_X86}, {'id': lzma.FILTER_DELTA, 'dist': 3}, {'id': lzma.FILTER_LZMA2, 'preset': 6}]))
open(d + '/multi.xz', 'wb').write(lzma.compress(t[:3000]) + bytes(8) + lzma.compress(t[3000:]))
open(d + '/multi.bz2', 'wb').write(bz2.compress(t[:3000], 1) + bz2.compress(t[3000:], 9))
try:
    from compression import zstd
    from compression.zstd import CompressionParameter as P
    big = t * 30 + os.urandom(20000) + bytes(300000)
    open(d + '/zbig.bin', 'wb').write(big)
    for name, opts in (('l1', {P.compression_level: 1, P.checksum_flag: 1}), ('l19', {P.compression_level: 19, P.checksum_flag: 1}), ('neg', {P.compression_level: -5}),
            ('nosize', {P.compression_level: 3, P.content_size_flag: 0}), ('long', {P.compression_level: 9, P.enable_long_distance_matching: 1, P.window_log: 22, P.checksum_flag: 1}),
            ('w10', {P.compression_level: 6, P.window_log: 10, P.checksum_flag: 1})):
        open(d + '/z-' + name + '.zst', 'wb').write(zstd.compress(big, options=opts))
    skip = (0x184D2A51).to_bytes(4, 'little') + (3).to_bytes(4, 'little') + b'abc'
    open(d + '/z-multi.zst', 'wb').write(skip + zstd.compress(big[:100000], options={P.checksum_flag: 1}) + zstd.compress(big[100000:]))
    with zipfile.ZipFile(d + '/zstd.zip', 'w', zipfile.ZIP_ZSTANDARD) as z:
        z.writestr('text.txt', t)
        z.writestr('big.bin', big)
except ImportError:
    pass
with zipfile.ZipFile(d + '/z64.zip', 'w', zipfile.ZIP_DEFLATED) as z:
    with z.open('text.txt', 'w', force_zip64=True) as w: w.write(t)
    z.writestr(zipfile.ZipInfo('Ünïcödé.txt'), b'utf8 name')
with zipfile.ZipFile(d + '/many.zip', 'w', zipfile.ZIP_STORED) as z:
    for i in range(66000): z.writestr('f/%05d' % i, b'%d' % i)
`);
    const f = (n) => fs.readFileSync(path.join(tmp, n));
    const props = (lc, lp, pb, dict) => { const p = new Uint8Array(5); p[0] = (pb * 5 + lp) * 9 + lc; new DataView(p.buffer).setUint32(1, dict, true); return p; };
    ok('lzma alone', eq(readAll(lzmaAloneStream(new Reader(bytesStream(f('a.lzma'))))), text));
    ok('lzma raw lc0 lp2 pb0 (end marker)', eq(readAll(lzmaStream(new Reader(bytesStream(f('raw1'))), props(0, 2, 0, 1 << 16))), text));
    ok('lzma2 raw', eq(readAll(lzma2Stream(new Reader(bytesStream(f('raw2'))), 18, { size: text.length })), text));
    for (const n of ['none', 'crc32', 'crc64', 'sha256']) ok('xz check ' + n, eq(readAll(xzStream(new Reader(bytesStream(f('c-' + n + '.xz'))))), text));
    ok('xz x86 + delta filters', eq(readAll(xzStream(new Reader(bytesStream(f('f.xz'))))), text));
    ok('xz two streams with padding', eq(readAll(xzStream(new Reader(bytesStream(f('multi.xz'))))), text));
    ok('bzip2 two streams', eq(readAll(bzip2Stream(new Reader(bytesStream(f('multi.bz2'))))), text));
    const bad = f('c-crc64.xz'); bad[bad.length - 40] ^= 4;
    try { readAll(xzStream(new Reader(bytesStream(bad)))); ok('xz damaged', false); } catch (e) { ok('xz damaged', /corrupt|checksum|truncated/.test(e.code), e.code); }
    if (fs.existsSync(path.join(tmp, 'zbig.bin'))) {
      const zbig = f('zbig.bin');
      for (const n of ['l1', 'l19', 'neg', 'nosize', 'long', 'w10', 'multi']) {
        try { ok('zstd ' + n, eq(readAll(zstdStream(new Reader(bytesStream(f('z-' + n + '.zst'))))), zbig)); } catch (e) { ok('zstd ' + n, false, e.code + ' ' + e.message); }
      }
      const bad = f('z-l1.zst'); bad[bad.length - 2] ^= 1;
      try { readAll(zstdStream(new Reader(bytesStream(bad)))); ok('zstd checksum error', false); } catch (e) { ok('zstd checksum error', e.code === 'checksum', e.code); }
      const za = open([path.join(tmp, 'z-l19.zst')]);
      ok('zstd file entry', za.format === 'zstd' && za.entries[0].size === zbig.length && za.entries[0].path === 'z-l19');
      const zz = open([path.join(tmp, 'zstd.zip')]);
      ok('zip Zstandard (method 93)', zz.entries.length === 2 && eq(readAll(zz.open(zz.entries[1])), zbig) && eq(readAll(zz.open(zz.entries[0])), text));
    }
    const z = open([path.join(tmp, 'z64.zip')]);
    ok('zip64 local header (python)', z.entries.length === 2 && eq(readAll(z.open(z.entries[0])), text) && z.entries[1].path === 'Ünïcödé.txt');
    const many = listZip(bytesSource(f('many.zip')));
    ok('zip64 end records (66000 entries)', many.zip64 && many.entries.length === 66000 && many.entries[65999].name === 'f/65999');
    const ma = open([path.join(tmp, 'many.zip')]);
    ok('zip64 archive', ma.info.props.some(([k]) => k === 'Zip64') && new TextDecoder().decode(readAll(ma.open(ma.entries[12345]))) === '12345');
  }
  ok('crc64 check value', (() => { const [lo, hi] = crc64(te.encode('123456789')); return lo === 0xdf1939fa && hi === 0x995dc9bb; })());
  ok('x86 BCJ leaves short input', FILTERS.x86(new Uint8Array(4), 4, 0, { mask: 0 }) === 0);
}

// --- test-only encoders ----------------------------------------------------------------------------------------

/** Unix compress (.Z): LZW, block mode, codes LSB first in groups of 8, padding at width changes and clears. */
export function compressZ(data, maxBits = 16) {
  const out = [0x1f, 0x9d, 0x80 | maxBits];
  let bits = 9, bb = 0, bc = 0, group = [];
  const flushGroup = (pad) => {
    // a group of 8 codes is `bits` bytes; partial groups are padded to full size when the width changes
    if (pad && group.length) { while (group.length < 8) group.push(null); }
    for (const c of group) { if (c !== null) { bb |= c << bc; bc += bits; } else bc += bits; while (bc >= 8) { out.push(bb & 255); bb >>>= 8; bc -= 8; } }
    if (pad && bc) { out.push(bb & 255); bb = 0; bc = 0; }
    group = [];
  };
  const emit = (c) => { group.push(c); if (group.length === 8) flushGroup(false); };
  const dict = new Map();
  let next = 257, w = -1, sinceClear = 0;
  const maxCode = 1 << maxBits;
  for (let i = 0; i < data.length; i++) {
    const c = data[i];
    if (w < 0) { w = c; continue; }
    const key = w * 256 + c;
    const v = dict.get(key);
    if (v !== undefined) { w = v; continue; }
    emit(w);
    if (next < maxCode) {
      dict.set(key, next++);
      if (next > (1 << bits) && bits < maxBits) { flushGroup(true); bits++; }
    } else if (++sinceClear > 3000) {
      // table full: clear it (exercises the decoder's clear handling)
      emit(256); flushGroup(true); bits = 9; dict.clear(); next = 257; sinceClear = 0;
    }
    w = c;
  }
  if (w >= 0) emit(w);
  flushGroup(false);
  if (bc) out.push(bb & 255);
  return Uint8Array.from(out);
}

function octal(n, len) { return n.toString(8).padStart(len - 1, '0') + '\0'; }
function tarHeader(name, { size = 0, type = '0', link = '', mtime = 1700000000, prefix = '', gnu = false, extra } = {}) {
  const h = new Uint8Array(512);
  const put = (s, o, n) => { const b = typeof s === 'string' ? te.encode(s) : s; h.set(b.subarray(0, n), o); };
  put(name, 0, 100); put(octal(0o644, 8), 100, 8); put(octal(0, 8), 108, 8); put(octal(0, 8), 116, 8);
  put(octal(size, 12), 124, 12); put(octal(mtime, 12), 136, 12); put('        ', 148, 8); put(type, 156, 1); put(link, 157, 100);
  if (gnu) put('ustar  \0', 257, 8); else { put('ustar\0', 257, 6); put('00', 263, 2); put(prefix, 345, 155); }
  if (extra) extra(h);
  let sum = 0;
  for (let i = 0; i < 512; i++) sum += h[i];
  put(octal(sum, 7) + ' ', 148, 8);
  return h;
}
const pad512 = (b) => { const n = Math.ceil(b.length / 512) * 512; const o = new Uint8Array(n); o.set(b); return o; };
const paxRecords = (recs) => te.encode(recs.map(([k, v]) => { const body = ` ${k}=${v}\n`; let n = body.length + 1; while (String(n).length + body.length !== n) n++; return n + body; }).join(''));
function sparseImage(map, size) { const out = new Uint8Array(size); const r = randomBytes(size, 77); for (const [o, l] of map) out.set(r.subarray(o, o + l), o); return out; }

/** A tar with the features listed in the test (written only for the test). */
export function makeTar(files) {
  const parts = [];
  for (const f of files) {
    if (f.dir) { parts.push(tarHeader(f.name, { type: '5' })); continue; }
    if (f.symlink) { parts.push(tarHeader(f.name, { type: '2', link: f.symlink })); continue; }
    if (f.hardlink) { parts.push(tarHeader(f.name, { type: '1', link: f.hardlink })); continue; }
    if (f.sparse) {
      // old GNU sparse ('S'): 4 map entries in the header, the rest in an extension block
      const img = sparseImage(f.sparse, f.size);
      const stored = Buffer.concat(f.sparse.map(([o, l]) => img.subarray(o, o + l)));
      const map = f.sparse;
      parts.push(tarHeader(f.name, { type: 'S', size: stored.length, gnu: true, extra: (h) => {
        map.slice(0, 4).forEach(([o, l], i) => { h.set(te.encode(octal(o, 12)), 386 + i * 24); h.set(te.encode(octal(l, 12)), 386 + i * 24 + 12); });
        h[482] = 0;
        h.set(te.encode(octal(f.size, 12)), 483);
      } }));
      parts.push(pad512(stored));
      continue;
    }
    if (f.paxSparse) {
      // pax GNU sparse 1.0: the map heads the data
      const img = sparseImage(f.paxSparse, f.size);
      const mapText = te.encode([f.paxSparse.length, ...f.paxSparse.flat()].join('\n') + '\n');
      const stored = Buffer.concat([pad512(mapText), ...f.paxSparse.map(([o, l]) => img.subarray(o, o + l))]);
      const pax = paxRecords([['GNU.sparse.major', '1'], ['GNU.sparse.minor', '0'], ['GNU.sparse.name', f.name], ['GNU.sparse.realsize', String(f.size)]]);
      parts.push(tarHeader('PaxHeaders/' + f.name, { type: 'x', size: pax.length }), pad512(pax));
      parts.push(tarHeader('GNUSparseFile.0/' + f.name, { size: stored.length }), pad512(stored));
      continue;
    }
    const d = f.data;
    if (f.pax) {
      const pax = paxRecords([['path', f.name], ['mtime', '1700000000.5']]);
      parts.push(tarHeader('PaxHeaders/x', { type: 'x', size: pax.length }), pad512(pax), tarHeader('short', { size: d.length }), pad512(d));
    } else if (f.gnuLong) {
      const n = te.encode(f.name + '\0');
      parts.push(tarHeader('././@LongLink', { type: 'L', size: n.length, gnu: true }), pad512(n), tarHeader(f.name.slice(0, 99), { size: d.length, gnu: true }), pad512(d));
    } else if (f.ustarPrefix) {
      const i = f.name.lastIndexOf('/');
      parts.push(tarHeader(f.name.slice(i + 1), { size: d.length, prefix: f.name.slice(0, i) }), pad512(d));
    } else parts.push(tarHeader(f.name, { size: d.length }), pad512(d));
  }
  parts.push(new Uint8Array(1024));
  return new Uint8Array(Buffer.concat(parts));
}

// --- fixture generation (run by hand: node archive/test.js --make-fixtures) ------------------------------------

export function makeFixtures() {
  if (!SZ || !PY) throw new Error('7-Zip and Python are needed to make the fixtures');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'archive-fix-'));
  const dir = path.join(tmp, 'src');
  writeTree(dir, makeTree(1));
  const out = {};
  const sz = (name, type, args) => { const f = path.join(tmp, name); exec(SZ, ['a', '-t' + type, f, '.', ...args], { cwd: dir }); out[name] = fs.readFileSync(f).toString('base64'); };
  sz('lzma2.7z', '7z', ['-m0=LZMA2', '-mx=9']);
  sz('bcj2.7z', '7z', ['-mf=BCJ2']);
  sz('arm64.7z', '7z', ['-m0=ARM64', '-m1=LZMA2']);
  sz('delta-bzip2.7z', '7z', ['-m0=Delta:2', '-m1=BZip2']);
  sz('pw-mhe.7z', '7z', ['-m0=LZMA2', '-pfixture', '-mhe=on']);
  sz('deflate64.zip', 'zip', ['-mm=Deflate64']);
  sz('lzma.zip', 'zip', ['-mm=LZMA']);
  sz('pw-crypto.zip', 'zip', ['-pfixture', '-mem=ZipCrypto']);
  sz('pw-aes.zip', 'zip', ['-pfixture', '-mem=AES256']);
  exec(PY, ['-c', `
import lzma, bz2, sys
d = sys.argv[1]
t = open(d + '/src/text.txt', 'rb').read()
open(d + '/text.xz', 'wb').write(lzma.compress(t[:1000], check=lzma.CHECK_SHA256) + bytes(4) + lzma.compress(t[1000:], filters=[{'id': lzma.FILTER_X86}, {'id': lzma.FILTER_LZMA2}]))
open(d + '/text.lzma', 'wb').write(lzma.compress(t, format=lzma.FORMAT_ALONE))
open(d + '/text.bz2', 'wb').write(bz2.compress(t))
from compression import zstd
from compression.zstd import CompressionParameter as P
open(d + '/text.zst', 'wb').write(zstd.compress(t, options={P.compression_level: 19, P.checksum_flag: 1}))
`, tmp]);
  for (const n of ['text.xz', 'text.lzma', 'text.bz2', 'text.zst']) out[n] = fs.readFileSync(path.join(tmp, n)).toString('base64');
  fs.rmSync(tmp, { recursive: true, force: true });
  return out;
}

if (isMain && process.argv.includes('--make-fixtures')) {
  const fx = makeFixtures();
  const file = fileURLToPath(import.meta.url);
  const src = fs.readFileSync(file, 'utf8');
  const body = 'const FIXTURES = {\n' + Object.entries(fx).map(([k, v]) => `  '${k}':\n    '${v}',`).join('\n') + '\n};\n';
  fs.writeFileSync(file, src.replace(/(\/\/ <fixtures>[^\n]*\n)[\s\S]*?(\/\/ <\/fixtures>)/, (m, a, b) => a + body + b));
  console.log('fixtures written:', Object.entries(fx).map(([k, v]) => `${k} ${v.length}`).join(', '));
} else if (isMain) process.exitCode = (await run()) ? 1 : 0;
